import { test, expect } from '@playwright/test';

test.describe('3. Онбординг — экран TrivoLN ID', () => {
  test('3.1 На экране «Your TrivoLN ID» нет кнопки «назад», есть только Continue @desktop @prod-safe (#636f6a7d0ecdb108f60d17fb)', async ({ page }) => {
    // 1. Открыть `/create-id`.
    await page.goto('/create-id');

    // 2. Дождаться заголовка экрана.
    await expect(page.getByText(/Your TrivoLN ID|ה-TrivoLN ID שלך/).first()).toBeVisible();

    // Индикатор шагов — шаг 3
    await expect(page.getByRole('progressbar')).toBeVisible();
    await expect(page.getByRole('progressbar').getByText('3', { exact: true })).toBeVisible();

    // Кнопки «назад» нет
    await expect(page.getByRole('button', { name: /back|חזרה|אחורה/i })).toHaveCount(0);

    // Кнопка «Continue» присутствует (не нажимать; «Try again» не нажимать)
    await expect(page.getByRole('button', { name: /Continue|המשך/ })).toBeVisible();
  });
});
